@_mutmut_mutated(mutants_x_reg_to_hack_symbol__mutmut)
def reg_to_hack_symbol(reg_name: str) -> str:
    """Map normalized MSP430 register name (r0..r15) to Hack predefined symbol."""
    reg = reg_name.lower()
    if reg in ("r0", "pc"):
        return "R0"
    if reg in ("r1", "sp"):
        return "SP"
    if reg in ("r2", "sr"):
        return "R2"
    if reg in ("r3", "cg"):
        return "R3"
    # r4..r15 -> R4..R15
    num = reg[1:]
    return f"R{num}"


